#recercadapermera-RF.rb
#Recercada Primera by Diego Ortiz 1553
#arranged for Sonic Pi by Robin Newman, Octover 2018

2.times do #play piece twice through

with_fx :reverb,pre_amp: 1.5,room: 0.65,mix: 0.55 do #add reverb
in_thread do #percussion track (played at half tempo)
use_bpm 220
56.times do
sample :drum_bass_hard,rate:1.4,amp: 0.4
sleep 2
sample :bd_tek,rate: 0.5,amp: 0.2
sleep 	1
sample :bd_tek,rate: 0.5,amp: 0.2
sleep 	1
end
end
uncomment do #comment when adjusting percussion track
use_bpm 440
with_fx :level, amp: 0.9 do #reduce overall level of playing parts
av=0.8;bv=0.2 #amp scaling for tune and other parts
use_synth :pluck
use_synth_defaults coef: 0.4 #adjust coef characteristic from norm 0.3

